// UI behavior for the standalone IRIS HTML prototype.
const {metrics, processes, startup} = window.IRIS_SAMPLE_DATA;
let alertMode=false;
function statusFor(m){const lo=m.avg-2*m.sd,hi=m.avg+2*m.sd;return m.value>=lo&&m.value<=hi?'ok':'check'}
function fmt(m,v){return Number(v).toLocaleString(undefined,{maximumFractionDigits:m.digits,minimumFractionDigits:m.digits})+(m.unit?' '+m.unit:'')}
function badge(s){return `<span class="status ${s==='ok'?'ok':s==='check'?'check':'alert'}">${s==='ok'?'Normal':s==='check'?'Review':'Alert'}</span>`}
function renderMetrics(){const rows=metrics.map(m=>{const s=statusFor(m);return `<tr><td><div class="metric-cell"><span class="metric-glyph">${m.icon}</span><div><strong>${m.name}</strong><div style="color:var(--muted);font-size:10px">${m.key}</div></div></div></td><td>${fmt(m,m.avg-2*m.sd)} – ${fmt(m,m.avg+2*m.sd)}</td><td><strong>${fmt(m,m.value)}</strong></td><td><span class="tag">${m.source}</span></td><td>${badge(s)}</td></tr>`}).join('');document.getElementById('allMetrics').innerHTML=rows;document.getElementById('overviewMetrics').innerHTML=metrics.slice(0,4).map(m=>`<tr><td>${m.name}</td><td>${fmt(m,m.value)}</td><td>${badge(statusFor(m))}</td></tr>`).join('');document.getElementById('baselineRows').innerHTML=metrics.map(m=>`<tr><td><strong>${m.key}</strong></td><td>${fmt(m,m.avg)}</td><td>${fmt(m,m.sd)}</td><td><span class="tag">${m.source}</span></td><td>First-run sample</td></tr>`).join('')}
function renderProcesses(filter=''){document.getElementById('processRows').innerHTML=processes.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase())).map(p=>`<tr><td><strong>${p.name}</strong></td><td>${p.memory}</td><td>${p.cpu}</td><td><span class="status ${p.status==='Normal'?'ok':p.status==='Moderate'?'check':'alert'}">${p.status}</span></td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">No matching processes</td></tr>'}
function renderStartup(filter=''){document.getElementById('startupRows').innerHTML=startup.filter(p=>p.name.toLowerCase().includes(filter.toLowerCase())).map(p=>`<tr><td><strong>${p.name}</strong></td><td>${p.scope}</td><td>${p.note}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-state">No matching applications</td></tr>'}
function setAlert(on){alertMode=on;const card=document.getElementById('diagnosisCard'),overview=document.getElementById('overviewDiagnosis');card.classList.toggle('warning',on);overview.classList.toggle('warning',on);document.getElementById('diagnosisTag').textContent=on?'ATTENTION':'ALL CLEAR';document.getElementById('diagnosisHeadline').innerHTML=on?'<span class="caution">! Disk I/O contention pattern</span>':'<span class="good">✓ All clear</span>';document.getElementById('diagnosisCopy').textContent=on?'The sample shows an unusually busy disk alongside a higher queue length. This pattern can indicate competing disk activity.':'Everything is within its normal range for your PC. We\'ll keep watching in the background.';document.getElementById('diagnosisRecommendation').innerHTML=on?'<strong>Recommended next step</strong>Check for background downloads, backups, or updates. Review the Processes & Disk tab before closing anything.':'<strong>Why this matters</strong>IRIS looks for patterns across metrics before declaring a root cause. One high number alone does not confirm a problem.';document.getElementById('memoryRuleStatus').textContent='No match in sample';document.getElementById('diskRuleStatus').textContent=on?'Pattern matched in demo':'No match in sample';document.getElementById('diskRuleStatus').className='status '+(on?'check':'ok');document.getElementById('overviewDiagnosis').querySelector('.big-status').innerHTML=on?'<span class="caution">! Review disk activity</span>':'<span class="good">✓ All clear</span>';document.getElementById('overviewDiagnosis').querySelector('p').textContent=on?'The sample disk signals are elevated. Review the disk queue and active disk time together.':'Everything is within its normal range for your PC. We\'ll keep watching in the background.';document.getElementById('overviewDiagnosis').querySelector('.tag').textContent=on?'SAMPLE ALERT':'NO ACTIVE ALERT';document.getElementById('eventPayload').textContent=on?JSON.stringify({rule_matched:'disk_io_contention',timestamp:'2026-10-14 16:42:08',metric_values:{disk_queue_length:{current:1.4,deviation_score:4.0},percent_disk_time:{current:88,deviation_score:5.2},available_ram_mb:{current:5324,deviation_score:-0.17}}},null,2):"No recent diagnostic event. The interface should show All Clear when no recent event exists."}
function navigate(view){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelectorAll('.view').forEach(s=>s.classList.toggle('active',s.id==='view-'+view));window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.goto)));document.getElementById('themeBtn').addEventListener('click',()=>{const html=document.documentElement;html.dataset.theme=html.dataset.theme==='dark'?'light':'dark';document.getElementById('themeBtn').innerHTML=html.dataset.theme==='dark'?'☼ &nbsp; Theme':'☾ &nbsp; Theme'});document.getElementById('toggleAlert').addEventListener('click',()=>setAlert(!alertMode));document.getElementById('refreshBtn').addEventListener('click',()=>{const m=metrics[0];m.value=Math.max(5,Math.min(65,m.value+(Math.random()*8-4)));document.getElementById('cpuVal').innerHTML=m.value.toFixed(1)+'<span style="font-size:14px">%</span>';document.getElementById('cpuBar').style.width=m.value+'%';renderMetrics();const t=document.getElementById('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1700)});document.getElementById('processSearch').addEventListener('input',e=>renderProcesses(e.target.value));document.getElementById('startupSearch').addEventListener('input',e=>renderStartup(e.target.value));renderMetrics();renderProcesses();renderStartup();
